// Named sequential jobs with durable terminals; no preview interaction.
import fs from 'node:fs';import assert from 'node:assert/strict';import {spawn} from 'node:child_process';import {fileURLToPath} from 'node:url';
import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261023-regional-tour-entry',root=stage+'/atlas',here=fileURLToPath(new URL('.',import.meta.url)).replace(/[\\/]$/,''),phase=process.argv[2];
const commands={native:['--test','scripts/test-regional-tour-entry.mjs'],player:['scripts/test-regional-tour-player.mjs'],types:['scripts/check-regional-tour-entry-types.mjs'],'types-v2':['scripts/check-regional-tour-entry-types.mjs'],'types-v3':['scripts/check-regional-tour-entry-types.mjs'],renderer:['scripts/body-renderer-revisions.mjs'],build:[here+'/build-ventricular-atlas-20261023.mjs'],'renderer-check':['scripts/body-renderer-revisions.mjs','--check']};
assert(commands[phase]);const index=here+'/CURRENT_CHECKPOINT.json';assert.equal(json(index).activeWork.current.ownerPreviewPolicy.restartPermitted,false);
const dir=stage+'/checks/'+phase;assert(!fs.existsSync(dir));fs.mkdirSync(dir,{recursive:true});
const write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n',{flag:'wx'}),out=fs.createWriteStream(dir+'/stdout.log',{flags:'wx'}),err=fs.createWriteStream(dir+'/stderr.log',{flags:'wx'});
const heap=['types-v2','types-v3'].includes(phase)?1536:phase==='types'?768:256,args=['--max-old-space-size='+heap,...commands[phase]],started={at:new Date().toISOString(),phase,cwd:root,args,previewChanged:false};
const child=spawn(process.execPath,args,{cwd:root,env:{...process.env,VM_TOUR_TYPE_PHASE:phase,NODE_OPTIONS:'--max-old-space-size='+heap,RAYON_NUM_THREADS:'1',GOMAXPROCS:'2'},stdio:['ignore','pipe','pipe'],windowsHide:true});
child.stdout.pipe(out);child.stderr.pipe(err);write(dir+'/STARTED.json',{...started,pid:child.pid,driverPid:process.pid});
function live(active){const p=json(index);p.activeWork.current.activeExecutionSessions=p.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='regional-tour-entry');if(active)p.activeWork.current.activeExecutionSessions.push({role:'regional-tour-entry',phase,pid:child.pid,driverPid:process.pid,evidence:dir,previewChanged:false});const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync(index,text);}live(true);console.log(JSON.stringify({phase,pid:child.pid}));
const result=await new Promise(resolve=>{child.once('error',e=>resolve({code:null,error:e.message}));child.once('close',(code,signal)=>resolve({code,signal}));});await Promise.all([out,err].map(s=>new Promise(resolve=>s.closed?resolve():s.once('close',resolve))));
